// MODZ kit — the way back to the hub from a mod's pane (DESIGN.md §9). While the hub runs it keeps
// `{ plugin: 'modz', key: 'isOn' }` true; a pane then draws `HomeButton` first, and its press writes the mod's
// own `{ plugin: '<mod>', key: 'home' }` value (`{ at }`). The hub hears it, comes forward, and opens again if
// it was closed, so the person always has a way back, even with one pane left and no tab to click.

// The resolved element table of the surface that draws the pane.
type Table = Record<string, any>

export const HOME_LABEL = '← MODZ'

export function HomeButton(ui: Table, onPress: () => void) {
  const { Box, Button } = ui

  return (
    <Box key="modz-home-row" flexDirection="row">
      <Button key="modz-home" label={HOME_LABEL} variant="secondary" onPress={onPress} />
    </Box>
  )
}

// The pane's tree with the way back above it; null while the hub is off draws the pane as it is.
export function withHome<T>(ui: Table, tree: T, onHome: (() => void) | null) {
  if (onHome === null) return tree
  const { Box } = ui

  return (
    <Box flexDirection="column" rowGap={1}>
      {HomeButton(ui, onHome)}
      {tree}
    </Box>
  )
}

files.hooks/pin.ts:
// MODZ kit — pinned press handles. Every element the JSX runtime builds gets a fresh handle, and the
// host releases a drawing's old handles the moment it redraws. A desktop holds the tree it last
// painted, so a click that lands just after any redraw (a state write, a focus flip, a poll) names a
// released handle and the engine drops it ("ui_press not handled"). The host keeps a handle alive
// across redraws when the new tree carries the same one, so each element here keeps the first handle
// its site and key ever got: every tree a surface still holds stays pressable, with the latest closure.
import type { RenderElement } from 'claude-code'

export type PinSite = { surface: string; component?: string; requestId?: string }

type Node = { type?: string; props?: { key?: unknown }; press?: { plugin: string; handle: number }; children?: unknown[] }

// Far above the runtime's own counter, which starts at 1 and climbs by one per element drawn.
const FIRST_PINNED = 1_000_000_000
const pins = new Map<string, number>()

function handleFor(id: string): number {
  let handle = pins.get(id)
  if (handle === undefined) {
    handle = FIRST_PINNED + pins.size
    pins.set(id, handle)
  }

  return handle
}

function pinNode(node: unknown, ctx: { site: string; seen: Map<string, number> }): unknown {
  if (typeof node !== 'object' || node === null) return node
  const el = node as Node
  const children = el.children?.map(child => pinNode(child, ctx))
  const withKids = children === undefined ? el : { ...el, children }
  // Only this plugin's own elements: the runtime names the plugin of every tree `next` returned.
  if (el.press?.plugin !== '' || typeof el.props?.key !== 'string') return withKids
  const base = `${ctx.site}\u0000${el.type}\u0000${el.props.key}`
  const nth = ctx.seen.get(base) ?? 0
  ctx.seen.set(base, nth + 1)

  return { ...withKids, press: { plugin: '', handle: handleFor(`${base}\u0000${nth}`) } }
}

// Return a render hook's tree through this: `return pinned(e, tree)`.
export function pinned<T extends RenderElement | null | undefined>(site: PinSite, tree: T): T {
  if (tree === null || tree === undefined) return tree
  const ctx = { site: `${site.surface}\u0000${site.component ?? ''}\u0000${site.requestId ?? ''}`, seen: new Map<string, number>() }

  return pinNode(tree, ctx) as T
}

files.hooks/stage.ts:
// MODZ kit — one panel (DESIGN.md §9). The hub and every mod's pane take turns in one place instead of
// piling up as tabs: a mod that opens its pane writes its own `{ plugin: '<mod>', key: 'shown' }` (`{ pane, at }`);
// the hub then steps aside and writes `{ plugin: 'modz', key: 'stage' }` naming that pane, and every other mod
// whose pane is open closes it. The hub coming back (its row, "← MODZ", /modz) writes the stage as `modz`.

export const HUB_PANE = 'modz'

export type Stage = { pane: string; at: number }

// The pane a `modz.open`, `modz.stage` or `shown` value names; null for anything malformed.
export const paneOf = (value: unknown): string | null => {
  if (typeof value !== 'object' || value === null) return null
  const pane = (value as { pane?: unknown }).pane

  return typeof pane === 'string' && pane !== '' ? pane : null
}

// Whether a `modz.open` write asks for this pane.
export const isAskedFor = (value: unknown, pane: string): boolean => paneOf(value) === pane

// Whether a `modz.stage` write puts another pane in the panel, so this one closes.
export function isOffStage(value: unknown, pane: string): boolean {
  const staged = paneOf(value)

  return staged !== null && staged !== pane
}

// What a mod writes under its own `shown` key once its pane is open.
export const shownOf = (pane: string, at: number): Stage => ({ pane, at })

